import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.junit.Test;
import java.io.IOException;
import java.util.Iterator;
import static org.junit.Assert.*;
import org.mockito.Mockito;

public class AttributesTest {

    @Test
    public void checkNotNullNotNullObjectTest() {
        String result = Attributes.checkNotNull("test");
        assertEquals("test", result);
    }

    @Test
    public void checkNotNullNullObjectTest() {
        String result = Attributes.checkNotNull(null);
        assertEquals("", result);
    }

    @Test
    public void getExistingKeyTest() {
        Attributes attributes = new Attributes();
        attributes.put("key", "value");
        assertEquals("value", attributes.get("key"));
    }

    @Test
    public void getNonExistingKeyTest() {
        Attributes attributes = new Attributes();
        String result = attributes.get("key");
        assertTrue(result.isEmpty());
    }

    @Test
    public void addNewAttributeTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        assertEquals(1, attributes.size());
    }

    @Test
    public void putUserDataTest() {
        Attributes attributes = new Attributes();
        attributes.putUserData("key", "value");
        assertEquals("value", attributes.getUserData("key"));
    }

    @Test
    public void putIgnoreCaseTest() {
        Attributes attributes = new Attributes();
        attributes.putIgnoreCase("Key", "value");
        assertTrue(attributes.hasKeyIgnoreCase("key"));
    }

    @Test
    public void hasDeclaredValueForKeyTest() {
        Attributes attributes = new Attributes();
        attributes.put("key", "value");
        assertTrue(attributes.hasDeclaredValueForKey("key"));
    }

    @Test
    public void iteratorTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        Iterator<Attribute> itr = attributes.iterator();
        assertTrue(itr.hasNext());
    }

    @Test
    public void asListTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        assertFalse(attributes.asList().isEmpty());
    }

    @Test
    public void htmlTest() throws IOException {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        Appendable appendable = new StringBuilder();
        attributes.html(appendable, Mockito.mock(Document.OutputSettings.class));
        assertTrue(appendable.toString().contains("value"));
    }

    @Test
    public void equalsTest() {
        Attributes attrs1 = new Attributes();
        attrs1.add("key", "value");
        Attributes attrs2 = new Attributes();
        attrs2.add("key", "value");
        assertTrue(attrs1.equals(attrs2));
    }

    @Test
    public void normalizeTest() {
        Attributes attributes = new Attributes();
        attributes.add("KEY", "value");
        attributes.normalize();
        assertTrue(attributes.hasKey("key"));
    }

    @Test
    public void deduplicateTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        attributes.add("key", "value");
        attributes.deduplicate(ParseSettings.htmlDefault);
        assertEquals(1, attributes.size());
    }

    @Test
    public void internalKeyTest() {
        String result = Attributes.internalKey("key");
        assertEquals("key", result);
    }
}
